    return read_ints()[0]


def check(nums, step, pre):
    suma = 0
    # print("Start: ", step)
    for x in nums:
        s = pre-x
        # print(pre, x, s)
        if abs(step-s) > 1:
            # print("BAD")
            raise Exception()
        if step == s:
            pre = x
            continue
        suma += 1
        if pre-(x+1) == step:
            pre = x+1
        else:
            pre = x-1
    # print("OK ", suma)
    return suma


