def solve(A):
    res = []
    last = 0
    while A:
        if max(A[0],A[-1]) <= last:
            return res

        if A[0] == A[-1]:
            v = A[0]-1
            for i,a in enumerate(A):
                if v < a:
                    v = a
                else:
                    break
            else:
                i += 1
