            _,op = max((L, ['L']*L), (R, ['R']*R))
            res.extend(op)
            return res

        v, op = min((v, op) for v,op in ((A[0], 'L'), (A[-1], 'R')) if v > last)
        last = v
        res.append(op)
        if op == 'L':
